    );
    const row = result.rows[0];
    if (row?.ssl !== true) {
      throw new Error("The Railway migration connection is not protected by SSL");
    }
    return {
      enabled: true,
      protocol: row.version ?? "unknown",
      cipher: row.cipher ?? "unknown",
      bits: Number(row.bits ?? 0),
    };
  } finally {
    await pool.end();
  }
}

